INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ec04c331-f7fc-460f-baed-f532f37df5c6', '21feff02-016d-46e2-bb9d-c27495133b1b', '20. óra: Összetett oszthatósági szabályok', 'Új oszthatósági szabályok alkotása (pl. 6-tal való oszthatóság).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "8d0e9f82-672d-424b-b2b2-7d130f9ed9fc", "text": "Mikor osztható egy szám 6-tal?", "type": "multiple-choice", "options": [{"id": "bd54d15e-95cf-4ef2-b91f-6f9c8d8fb184", "text": "Ha 2-vel és 3-mal is osztható egyszerre (páros és a számjegyösszeg 3-mal osztható)", "isCorrect": true}, {"id": "2b95f0d4-3f50-4363-a7fe-e531868c86cc", "text": "Ha 6-ra végződik", "isCorrect": false}, {"id": "f028032f-89e1-4bc2-a83d-5aa30f29bf10", "text": "Ha a számjegyek összege 6", "isCorrect": false}, {"id": "03efba44-655f-41ba-9b3f-1f81fe62c0d7", "text": "Ha 12-vel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "9cf77f9e-a0cd-47af-8c1e-3672db7e6d37", "text": "Mikor osztható egy szám 15-tel?", "type": "multiple-choice", "options": [{"id": "7c11c4b6-31af-4d8c-8bf9-a46b1ec72cbb", "text": "Ha 3-mal és 5-tel is osztható egyszerre", "isCorrect": true}, {"id": "55f1e4c6-05a0-4810-9d73-e2d179ac7852", "text": "Ha 15-re végződik", "isCorrect": false}, {"id": "9b6d41d6-5430-4b4d-9362-9608f7c79782", "text": "Ha páratlan", "isCorrect": false}, {"id": "6b24cf5a-bde2-4ae4-b693-c3b5792db94d", "text": "Ha 5-tel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "aaa28bc6-d9ba-4e25-af71-14fa2f662284", "text": "A 132 osztható 6-tal (páros és 1+3+2=6).", "type": "true-false", "options": [{"id": "7b221900-6840-4fcb-a9b8-7d5f86d4e377", "text": "Igaz", "isCorrect": true}, {"id": "3929e290-2850-42e4-80cb-1f9daa6d2a07", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "879b8003-923a-4853-9b68-fd3e1c703372", "text": "A 45 osztható 15-tel.", "type": "true-false", "options": [{"id": "6ca24e2d-39d6-436d-8aa9-9943009066bc", "text": "Igaz", "isCorrect": true}, {"id": "1f7c79fb-5651-4009-a24c-3bca94aa1faa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d2448857-5143-4960-8758-8887242931f1", "text": "Mikor osztható egy szám 12-vel?", "type": "multiple-choice", "options": [{"id": "23225caf-7d12-442e-aeea-2cfd59ad7d4c", "text": "Ha 3-mal és 4-gyel is osztható", "isCorrect": true}, {"id": "89869399-f1d9-4501-869a-0393821208fd", "text": "Ha 2-vel és 6-tal", "isCorrect": false}, {"id": "b8fddfa7-9c0d-453c-92b3-fc8ee1e11bfc", "text": "Ha 12-re végződik", "isCorrect": false}, {"id": "0101a4de-befd-44ee-9b6e-22241e4980a4", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "80e51645-0842-40de-8658-ec632e5e444a", "text": "Osztható-e a 210 6-tal?", "type": "true-false", "options": [{"id": "281e6b0c-663c-41d6-950e-aaa321838773", "text": "Igaz (páros, 2+1+0=3)", "isCorrect": true}, {"id": "add723aa-06b8-4bbb-b591-1658fbff47df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "537684b1-406e-4d4f-bc86-d04b1a34e756", "text": "Melyik számjegy tehető a 34_ végére, hogy osztható legyen 6-tal? (páros kell és 3+4+X osztható 3-mal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('77aaea5a-20db-4fd4-aa83-e12201ccc881', '21feff02-016d-46e2-bb9d-c27495133b1b', '21. óra: Gyakorlóóra: a tanult oszthatósági szabályok alkalmazása', 'Gyakorlás, igaz-hamis állítások, halmazábrák oszthatóságra.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9377d948-ba47-41b9-8bd0-841e58e0aed5", "text": "Melyik szám osztható 2-vel, 3-mal és 5-tel is (azaz 30-cal)?", "type": "multiple-choice", "options": [{"id": "6470dd40-6a56-4d2c-aef2-5268f649e5b7", "text": "90", "isCorrect": true}, {"id": "0067c0d6-4739-44db-88fc-8c3cee98558b", "text": "45", "isCorrect": false}, {"id": "cd1d5dc7-8bea-4fbf-8bd1-f8a0a2f8accf", "text": "80", "isCorrect": false}, {"id": "5a52a9cd-e4a2-42ca-b9e6-0b09830ce2f7", "text": "100", "isCorrect": false}], "timeLimit": 15}, {"id": "c4950797-66e1-468d-9b11-b0dd80d9d249", "text": "A 180 osztható 4-gyel és 9-cel is.", "type": "true-false", "options": [{"id": "5eb6639b-1351-46ed-8282-ea5cd3529a07", "text": "Igaz", "isCorrect": true}, {"id": "ccd47332-bbc1-4727-90a9-dbc213e893ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4055dd22-d7ca-47ec-ad67-f5eb2d8b5b94", "text": "Hány olyan szám van 1 és 100 között, ami osztható 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "b3bedfb5-d2e4-49ee-9f36-b9ec6d3458be", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "cc78e270-9208-4e47-988c-c5535280088a", "text": "729 (7+2+9=18)", "isCorrect": true}, {"id": "cfff97c3-4684-428f-afc7-2a4537b186a2", "text": "721", "isCorrect": false}, {"id": "c9d51a7e-8f3a-4c0a-a6e9-fba95ba7cf27", "text": "725", "isCorrect": false}, {"id": "5e28737d-152c-4bab-9f61-2b295cba2b94", "text": "730", "isCorrect": false}], "timeLimit": 15}, {"id": "1fa69626-5222-4dbc-80bf-33a44650cffa", "text": "Ha egy szám osztható 10-zel, akkor 5-tel is osztható.", "type": "true-false", "options": [{"id": "2e3c2cad-3f4b-48c4-903f-640aac643da4", "text": "Igaz", "isCorrect": true}, {"id": "b78d2a13-f1bc-45ab-bcd0-1a003c30c240", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "750a6a3b-2f3c-4a3b-9d8b-94b810f9d3b9", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 5-tel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4592434c-0d8a-4ec3-a788-d077393ff05b", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 3-mal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "102"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c504e10f-cee6-422c-904c-d773fcbd105f', '21feff02-016d-46e2-bb9d-c27495133b1b', '22. óra: Többszörös, közös többszörös', 'Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "04b768ae-3229-4d06-af8f-a2dc647c4a8d", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "6c3d1df1-d16f-4a2d-8eb8-282c41ff0fb3", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "6b715e04-ccf5-41d2-baff-2b6d52436758", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "3c3e49f3-47b8-49d6-a4a2-aafec250b94a", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "181b4d82-4801-4a82-a5fa-55f731ecc9b9", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "276f65a4-b314-4d26-b144-71939832811c", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "0bffb2d0-e373-418f-94c4-e1821ec8fba7", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "716dbccd-6c07-4a8a-84f0-df56c550b8aa", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "1da62336-c632-473a-8071-8b080ddfa7f7", "text": "Igaz", "isCorrect": true}, {"id": "6096679a-a4f0-4906-b7e1-237a079b454b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2644d134-5752-448b-819c-77ba9f180e31", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "3f1e082a-34b1-423e-81e6-c7c23ab65a95", "text": "Igaz", "isCorrect": true}, {"id": "3e745cb1-97bb-45c9-9962-05f79a37653e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "616b0d85-9679-4176-ab40-0ab187a469ff", "text": "Mennyi a 6 és 8 legkisebb közös többszöröse?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "825a43b6-c3a8-477f-a31d-d9064e3f20dd", "text": "Melyik szám közös többszöröse a 2-nek és a 5-nek?", "type": "multiple-choice", "options": [{"id": "d6eb2eda-7900-406f-9a18-638d42b40485", "text": "10", "isCorrect": true}, {"id": "655f7e17-b977-4a0f-b102-32e3baf19285", "text": "15", "isCorrect": false}, {"id": "0ad9b241-922c-4df7-8c73-611e5367c9a1", "text": "8", "isCorrect": false}, {"id": "021d33b9-d9f0-4950-ad26-c6e16ebc10aa", "text": "12", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fb7ba6fd-4a37-48f7-86b3-36cc7b24bcf3', '21feff02-016d-46e2-bb9d-c27495133b1b', '23. óra: Osztó, közös osztó', 'Közös osztók, legnagyobb közös osztó (lnko) és törtek egyszerűsítése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "503fe660-02aa-419c-b599-c528228f4d1e", "text": "Mit jelent két szám legnagyobb közös osztója (lnko)?", "type": "multiple-choice", "options": [{"id": "749ebe15-6248-4128-8c46-5c95a67e413a", "text": "A legnagyobb olyan pozitív számot, amely mindkét számot osztja", "isCorrect": true}, {"id": "5dd6ab1a-ef46-4c16-a5ea-48a01d08857c", "text": "A két szám összege", "isCorrect": false}, {"id": "6ce8d0c3-928a-41b4-aef5-3df8eda30539", "text": "A legkisebb többszöröst", "isCorrect": false}, {"id": "bf361146-06d0-4a70-8a4f-5d9d8ce3a371", "text": "Az 1-et mindig", "isCorrect": false}], "timeLimit": 15}, {"id": "b6b4c3fd-07eb-4e17-b241-dfbaebc7865f", "text": "Mennyi a 12 és 18 legnagyobb közös osztója, lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6b2aa315-d781-4ef6-80ca-ae7f3c1fccb4", "text": "Mennyi a 15 és 25 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "34dae026-e44f-4d2c-b0e4-6515865f03f6", "text": "Két számot relatív prímeknek nevezünk, ha a legnagyobb közös osztójuk 1.", "type": "true-false", "options": [{"id": "b88cbed3-e2ae-4244-8b5c-5f1eebb0a322", "text": "Igaz", "isCorrect": true}, {"id": "95a5fc76-9dfd-4db5-9ed2-6c2f735fa9fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b8c0df8c-b90f-4f9c-9c18-d32aedba9eab", "text": "A 8 és 9 relatív prímek (lnko(8,9) = 1).", "type": "true-false", "options": [{"id": "40a96c32-0b51-4564-acd7-f1e91e065d32", "text": "Igaz", "isCorrect": true}, {"id": "ade1b3b1-03e8-472d-b4a1-8eccaca09a8e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4387a2f4-42bc-4ba7-885c-b60ea5332301", "text": "A legnagyobb közös osztóval egyszerűsítve a törtet a legegyszerűbb alakot kapjuk.", "type": "true-false", "options": [{"id": "ef38b260-3f08-4826-b2df-601e53244737", "text": "Igaz", "isCorrect": true}, {"id": "93ac67f3-ceb6-4aef-ba0f-9b12356f56ed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ffd1435-65eb-4ec3-82ae-ef67c82c212d", "text": "Mennyi a 20 és 30 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f2ef7e62-5252-4df3-b4ac-961a536d07cf', '21feff02-016d-46e2-bb9d-c27495133b1b', '24. óra: Összefoglalás', 'A tanult fogalmak ismétlése, rendszerezése az egész számok és oszthatóság témakörből.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "c9d1eed4-325c-4689-9cf7-58080dabe005", "text": "Mennyi (-12) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "9532d9e0-86c4-4b4e-8ae4-c96e243886a8", "text": "Mennyi lkkt(6, 9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "90e879e8-f901-4448-9bce-65f5e467db62", "text": "Mennyi lnko(24, 36)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "e5425204-989d-4594-8dcf-43b5ecb89680", "text": "A 135 osztható 5-tel és 9-cel is.", "type": "true-false", "options": [{"id": "486e38d6-ed22-4a78-89a7-d1e9c5d3d3a7", "text": "Igaz", "isCorrect": true}, {"id": "0cd334af-7e9e-49d0-8f55-09118410069a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4da5d2e1-7186-418f-a184-c79e8ef1f134", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "1515ac9b-e49a-4b8c-9ee4-de18f46d6ae6", "text": "Igaz", "isCorrect": true}, {"id": "44a10a84-a245-44b5-91ca-9338679578db", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a39bc134-2302-4471-803b-d8aa6fb469a6", "text": "Mennyi (-50) : (+10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "8373b038-97db-476d-846c-ab5db1f0b92d", "text": "Melyik szám osztható 4-gyel?", "type": "multiple-choice", "options": [{"id": "ef21f437-c32b-4e3a-908d-7e617bd52c4f", "text": "524", "isCorrect": true}, {"id": "f483ce06-54e1-47c0-9811-d08eee52464c", "text": "522", "isCorrect": false}, {"id": "4dba30e4-e2ef-4a0e-95e1-ba4d5f1f498f", "text": "521", "isCorrec