INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1a34536e-43a6-4104-ab5f-3c6955052ff1', '21feff02-016d-46e2-bb9d-c27495133b1b', '25. óra: Tesztfeladatok megoldása', 'Feladatmegoldási gyakorlat önállóan az oszthatósági téma lezárása előtt.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "f0330c61-325c-4dc2-bb29-bcafda097d73", "text": "Hány osztója van a 10-nek? (1, 2, 5, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "4c51e65c-1d2c-45b3-806b-ee0182d0e9ab", "text": "Osztható-e a 432 6-tal?", "type": "true-false", "options": [{"id": "1d3270b4-8299-4f03-b4c1-24f833a01286", "text": "Igaz (páros és 4+3+2=9)", "isCorrect": true}, {"id": "6246116b-cd24-4faf-a1a6-88ee814eb3ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8b02fac-69f4-47af-9588-c5bba5137511", "text": "Mennyi (-7) * (+6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-42"}, {"id": "d0a9a09a-e5e6-4b63-9f82-3c2b3c3620f6", "text": "Melyik szorzat eredménye pozitív?", "type": "multiple-choice", "options": [{"id": "15da0bb5-ff71-43c9-a47c-61504103c8de", "text": "(-4) * (-5)", "isCorrect": true}, {"id": "87f550c3-1b22-4e14-a582-344b4df75815", "text": "(-4) * (+5)", "isCorrect": false}, {"id": "1de0cc9f-d45c-4549-a032-c5dda265c351", "text": "(+4) * (-5)", "isCorrect": false}, {"id": "0b4ff1b5-0819-4abf-8819-c8c9829112b7", "text": "(-4) * 0", "isCorrect": false}], "timeLimit": 15}, {"id": "010ab04a-9c32-4b6c-9109-65927cd33ac8", "text": "Mennyi a maradék, ha 47-et 5-tel osztunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "6b111eaf-a791-4593-af57-bacb96e6a940", "text": "A 17 prímszám.", "type": "true-false", "options": [{"id": "b91c3bfd-469b-4609-97ee-423f8c5b40b0", "text": "Igaz", "isCorrect": true}, {"id": "4757d6b9-70b0-43b2-b664-1b68dd767104", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "76449f58-5de1-47bb-8fbe-cc70327f30ea", "text": "Mennyi lkkt(4, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('102bcd8c-c0af-442d-a4a3-375a437fd144', '21feff02-016d-46e2-bb9d-c27495133b1b', '26. óra: Témazáró dolgozat', 'Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0035a093-940c-47f3-80a5-ccc57a02d339", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d44e05e0-ab50-4008-af4f-81c910c1c8a3", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "aa2b86ec-f25f-48a3-93fe-308318739895", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "f2217fc3-23ac-4f4a-abf6-242f6e01c947", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "3875917e-4fba-4f45-8426-22731c4d57a8", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "49f4648c-01af-4f0b-a98c-85fc5be5d381", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "77bd0ce5-c52b-47c6-ad4f-7635a1531be7", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "9d2260d9-49b5-4100-8194-238b639b2c4c", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "24ae659f-db56-41c3-8b15-7879c41ca66b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cbe826fa-fd72-464c-b465-41a40b0c787c", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "aefeedff-4ea9-4573-9477-32f966bdf082", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "f754a8ff-0730-493e-b946-d0a165e147c0", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "0d1d9597-2292-45af-8afa-4225baef300d", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "af213a1b-7fb4-4114-a575-5832a3e2601e", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "ff7bb368-4e0e-41fa-8d6b-f63e8862ea9f", "text": "Igaz", "isCorrect": true}, {"id": "360fc7d9-2e65-4fe7-a6e3-b5a85557149f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1a9d7256-0ac4-46eb-944a-643263fcc4ba', '21feff02-016d-46e2-bb9d-c27495133b1b', '27. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "16d8210c-4cfe-481f-8505-32fe853b988b", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "33e5066e-e724-4230-bec5-445dacf9c8f1", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "dd2116f6-25b7-43cc-a1ba-72504d250cd3", "text": "A számok leírása", "isCorrect": false}, {"id": "d8680866-cb98-445b-bf44-92435315400a", "text": "A vonalzó használata", "isCorrect": false}, {"id": "d8517240-75b6-41b4-a09f-dba0dd0c3d34", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "eb3fdade-ed95-41a2-b3a9-6a34dc7bdc17", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "76bfa22c-76d5-48c8-a65f-b6629b0cae2e", "text": "Igaz", "isCorrect": true}, {"id": "af2ac38e-4ab1-47ff-a095-bfa5db365595", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d0384219-5f39-4260-8268-2fc97162b803", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "946aaf5a-412a-4d0f-8da5-ba5c78207557", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "3e49605b-0dd9-4838-8acb-2eea5f2b26eb", "text": "Igaz", "isCorrect": true}, {"id": "79c95cba-e410-4b40-88ec-57f25dc76a66", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "40d8a94b-7dac-44c1-886e-33e90527a6b8", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "40bf3059-ab87-4aa9-9298-d2ab08423674", "text": "A dolgozatok áttekintése segít a hiányosságok pótlásában.", "type": "true-false", "options": [{"id": "300ca24e-8043-4257-b521-1b7d98ac3c32", "text": "Igaz", "isCorrect": true}, {"id": "5a17a754-bff5-4cce-9a3e-a93fbd10bccc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "43fced40-56e3-4c7b-9f46-9520bb27dcea", "text": "Mennyi lnko(10, 15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b1be3872-9996-44f6-bc7e-26c09dc16e1c', '21feff02-016d-46e2-bb9d-c27495133b1b', '28. óra: Mit tanultunk a törtekről? Ismétlés', 'Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "54660d33-3d83-40a2-bdfd-efcfc035a43f", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "79ea9fc7-241d-442c-a123-fb840e9a8c8f", "text": "Számláló", "isCorrect": true}, {"id": "c80aaf4f-5bf3-47df-a667-d80f1584f57c", "text": "Nevező", "isCorrect": false}, {"id": "6c3f6def-32d8-4173-8cb6-dcd055a0ad86", "text": "Törtvonal", "isCorrect": false}, {"id": "687e1b95-9d12-4b57-b065-5c1487b2405c", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "91f38f3d-9bb0-49e7-80b8-3cac83446255", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "9958abb2-a23d-4187-8b69-ce6a170faffd", "text": "Nevező", "isCorrect": true}, {"id": "4312e81f-9039-4d56-a877-755938c9c244", "text": "Számláló", "isCorrect": false}, {"id": "b6618ef4-b1c7-4374-85e0-90db576b8145", "text": "Osztó", "isCorrect": false}, {"id": "687940d7-c115-4cf9-90fc-15a933376985", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "5299cdb3-effa-4655-8b8a-3f1598cbe69e", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "726045c7-993a-48e6-adc5-9b1412c7a53b", "text": "6/8", "isCorrect": true}, {"id": "1b17a133-e168-4a3c-b109-5b8bbc190864", "text": "5/6", "isCorrect": false}, {"id": "b3b9a60c-b049-46b3-8ee7-b3f37cd1f32a", "text": "3/8", "isCorrect": false}, {"id": "fa68d597-83b1-4e10-94d4-b9f2ed5076a5", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "086e7f6c-b9c9-4955-8e25-341ba06d868a", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "f2135603-2a59-4f4b-a682-13212d3063ed", "text": "3/5", "isCorrect": true}, {"id": "c4d410c5-feba-4c8b-acbe-b2bf81ac17b1", "text": "3/10", "isCorrect": false}, {"id": "efcf9582-8ec0-4335-8600-f83c03768287", "text": "6/5", "isCorrect": false}, {"id": "41434f44-e24b-4305-b9f4-80fb79be7559", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "08869114-87c6-4e4c-a380-d23de5421ac3", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "b20d42ff-c30b-46b7-bc89-d5a2c87c7502", "text": "Igaz", "isCorrect": true}, {"id": "ccaa36b8-7ef2-4a92-8990-d4afd2ddb149", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "18af4582-63e1-4bf9-89f7-7af7ae0b68ea", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "c77b543d-316b-41c1-b702-26a39c12fed8", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "4aed324f-5eaf-4b8d-8396-9bc8a3912c94", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "e67a2570-98a6-4f68-bb64-9b11dc21c6b3", "text": "2/6", "isCorrect": false}, {"id": "8dc9bf14-8b73-446e-9609-7895eb7cc0f9", "text": "2/4", "isCorrect": false}, {"id": "c906702c-14ba-4028-bc00-b4e3c38b4982", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0ddcc441-16ca-4109-bc88-10320d7ad2a3', '21feff02-016d-46e2-bb9d-c27495133b1b', '29. óra: Mit tanultunk a törtekről? Ismétlés II.', 'Összeadás és kivonás azonos és különböző nevezőjű törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "eda13147-1206-4c90-8720-4238edbd5d30", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "53f573b3-4e47-452f-a13c-c3fb27a35894", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "b0f706e4-1311-441a-8843-39bcd64a5dc1", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "9b92c1b3-a53d-43b2-bbfa-d4ac9dfb47af", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "0c44f29b-0bff-4716-9def-8562bb518bc2", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "97904bb6-2869-4357-bf7a-32dfffcc4875", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "44b455ab-48fc-4d94-a04b-629b497423f8", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "164fe568-48df-49b1-beca-3177c3d78948", "text": "2/9", "isCorrect": false}, {"id": "e2e6069c-8723-46a2-bb0c-db2d74435af3", "text": "1/9", "isCorrect": false}, {"id": "ba42ba82-f59f-4167-bbf1-fe1585cda495", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "d0ba1be9-4be5-4a0c-9d46-dfa1832d371d", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "f05cba9f-2464-4ae6-a2aa-9b942491b7a3", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "677f7f0a-1a52-4b25-a40f-94945a3f27b4", "text": "2/0", "isCorrect": false}, {"id": "5d1a0992-25c4-4f30-ac90-df17df8c5f3f", "text": "8/8", "isCorrect": false}, {"id": "d6428b9d-a3f9-48fc-976e-575d6bdaa6f4", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "ccad51f3-f3fb-4f36-af22-ff5aacdead1e", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "bb83c54b-61c1-4863-8c84-b38232e33738", "text": "Igaz", "isCorrect": true}, {"id": "61475310-5da9-4a4e-915d-3076c87c14f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "703f851e-21f0-4358-9a4a-1971daf1f936", "text": "Hány nyolcad van 3/4-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "efd41253-3874-44d8-b013-8dcd4cd950ba", "text": "Mennyi 1 egészből kivonva 2/5-öt?", "type": "multiple-choice", "options": [{"id": "c919c5df-52f5-4fb4-b105-820e5869cb3c", "text": "3/5", "isCorrect": true}, {"id": "70c0c221-4a6b-4d4e-a6ae-ddddbbeb046e", "text": "1/5", "isCorrect": false}, {"id": "693c127d-4a45-4c3b-96e8-ba4f2381fcad", "text": "2/5", "isCorrect": false}, {"id": "40d1f997-df2c-497a-b5a6-9cc5f9a53902", "text": "5/5", "isCorrect": false}], "timeLimit": 15}, {"id": "75809678-81fd-4958-9656-422565b23878", "text": "A törtvonal osztás műveletet jelent.", "type": "true-false", "options": [{"id": "b8a023b4-4c10-46f5-9900-788107c09dd5", "text": "Igaz", "isCorrect": true}, {"id": "7277b082-dad8-4f44-95fc-5fe15e07a713", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());